21	type manifestResponse struct {
22		CID       string   `json:"cid"`
23		Size      int      `json:"size"`
24		ChunkSize int      `json:"chunkSize"`
25		Chunks    []string `json:"chunks"`
26	}
27	
28	func writeJSON(w http.ResponseWriter, status int, body any) {
29		w.Header().Set("Content-Type", "application/json")
30		w.WriteHeader(status)
31		_ = json.NewEncoder(w).Encode(body)
32	}
33	
34	func writeError(w http.ResponseWriter, status int, code string) {
35		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
36	}
37	
38	// postObject handles POST /v1/objects.
39	func (s *store) postObject(w http.ResponseWriter, r *http.Request) {
40		if r.Method != http.MethodPost {
41			w.Header().Set("Allow", http.MethodPost)
42			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
43			return
44		}
45		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
46		if err != nil || mediaType != "application/octet-stream" {
47			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
48			return
49		}
50		body, err := io.ReadAll(io.LimitReader(r.Body, MaxObjectSize+1))
51		if err != nil {
52			writeError(w, http.StatusBadRequest, "invalid_request")
53			return
54		}
55		if len(body) > MaxObjectSize {
56			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
57			return
58		}
59	
60		obj := newObject(body)
61		stored, created := s.put(obj, auditObjectUpload, nil)
62		status := http.StatusOK
63		if created {
64			status = http.StatusCreated
65		}
66		writeJSON(w, status, objectResponse{
67			CID:       stored.cid,
68			Size:      stored.size,
69			ChunkSize: ChunkSize,
70			Chunks:    stored.cids,
71			Created:   created,
72		})
73	}
74	
75	// newObject splits a body into chunks under the fixed rules and derives its
76	// root identifier from the resulting manifest.
77	func newObject(body []byte) *object {
78		obj := &object{size: len(body), chunks: [][]byte{}, cids: []string{}}
79		for start := 0; start < len(body); start += ChunkSize {
80			end := start + ChunkSize
81			if end > len(body) {
82				end = len(body)
83			}
84			chunk := body[start:end]
85			obj.chunks = append(obj.chunks, chunk)
86			obj.cids = append(obj.cids, chunkCID(chunk))
87		}
88		obj.cid = rootCID(obj.size, obj.cids)
89		return obj
90	}
91	
92	// lookupObject validates the path identifier and resolves the object,
93	// writing the appropriate error response on failure.
94	func (s *store) lookupObject(w http.ResponseWriter, r *http.Request) *object {
95		cid := r.PathValue("cid")
96		if !validCID(cid) {
97			writeError(w, http.StatusBadRequest, "invalid_cid")
98			return nil
99		}
100		obj := s.get(cid)
101		if obj == nil {
102			writeError(w, http.StatusNotFound, "object_not_found")
103			return nil
104		}
105		return obj
106	}
107	
108	// getObject handles GET /v1/objects/{cid}.
109	func (s *store) getObject(w http.ResponseWriter, r *http.Request) {
110		if r.Method != http.MethodGet {
111			w.Header().Set("Allow", http.MethodGet)
112			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
113			return
114		}
115		obj := s.lookupObject(w, r)
116		if obj == nil {
117			return
118		}
119		w.Header().Set("Content-Type", "application/octet-stream")
120		w.Header().Set("Content-Length", strconv.Itoa(obj.size))
121		for _, chunk := range obj.chunks {
122			_, _ = w.Write(chunk)
123		}
124	}
125	
126	// getManifest handles GET /v1/objects/{cid}/manifest.
127	func (s *store) getManifest(w http.ResponseWriter, r *http.Request) {
128		if r.Method != http.MethodGet {
129			w.Header().Set("Allow", http.MethodGet)
130			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
131			return
132		}
133		obj := s.lookupObject(w, r)
134		if obj == nil {
135			return
136		}
137		writeJSON(w, http.StatusOK, manifestResponse{
138			CID:       obj.cid,
139			Size:      obj.size,
140			ChunkSize: ChunkSize,
141			Chunks:    obj.cids,
142		})
