			http.NotFound(w, r)
			return
		}
		s.refObjectEntry(w, r, segments[0], rawQuery)
	default:
		http.NotFound(w, r)
	}
}

// decodeRefName percent-decodes a single raw name segment exactly once and
// validates it against the name contract.
