	// are not refs routes.
	for _, target := range []string{"/v1/refs/a/other", "/v1/refs/a/object/extra", "/v1/refs", "/v1/refs/"} {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, target, nil))
