49	// "/v1/refs/{name}/object"; anything else is no route. The raw query
50	// string is carried through verbatim so handlers never depend on r.URL,
51	// which is unset for raw-target requests.
52	func (s *store) refsDispatch(w http.ResponseWriter, r *http.Request) {
53		target := r.RequestURI
54		if target == "" {
55			target = r.URL.EscapedPath()
56		}
57		rawPath, rawQuery, _ := strings.Cut(target, "?")
58		rest := rawPath[len(refsPrefix):]
