85	func (s *store) refByID(w http.ResponseWriter, r *http.Request, rawName, rawQuery string) {
86		if r.Method != http.MethodGet && r.Method != http.MethodPut {
87			w.Header().Set("Allow", "GET, PUT")
88			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
89			return
90		}
91		name, ok := decodeRefName(rawName)
92		if !ok {
93			writeError(w, http.StatusBadRequest, "invalid_ref")
94			return
95		}
96		if r.Method == http.MethodPut {
