106		if err != nil || mediaType != "application/json" {
107			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
108			return
109		}
110		body, err := io.ReadAll(r.Body)
111		if err != nil {
112			writeError(w, http.StatusBadRequest, "invalid_request")
113			return
114		}
115		if !wellFormedJSON(body) {
116			writeError(w, http.StatusBadRequest, "invalid_request")
117			return
118		}
119		var req refPutRequest
120		dec := json.NewDecoder(bytes.NewReader(body))
121		dec.DisallowUnknownFields()
122		if err := dec.Decode(&req); err != nil {
123			writeError(w, http.StatusBadRequest, "invalid_request")
124			return
125		}
126		if req.CID == nil || req.ExpectedRevision == nil {
127			writeError(w, http.StatusBadRequest, "invalid_request")
128			return
129		}
130		expected, err := parseInt(req.ExpectedRevision)
131		if err != nil || expected < 0 {
132			writeError(w, http.StatusBadRequest, "invalid_request")
133			return
134		}
135		var cidPtr *string
136		if err := json.Unmarshal(req.CID, &cidPtr); err != nil || cidPtr == nil {
137			writeError(w, http.StatusBadRequest, "invalid_request")
138			return
139		}
140		if !validCID(*cidPtr) {
141			writeError(w, http.StatusBadRequest, "invalid_cid")
142			return
143		}
144		cid := *cidPtr
145		rev, created, code := s.commitRef(name, cid, int64(expected), time.Now())
146		switch code {
147		case "object_not_found":
148			writeError(w, http.StatusNotFound, code)
149			return
150		case "revision_conflict":
151			writeError(w, http.StatusConflict, code)
152			return
153		}
154		status := http.StatusOK
155		if created {
156			status = http.StatusCreated
157		}
158		writeRef(w, status, name, rev)
159	}
