161	// getRef handles GET /v1/refs/{name}. Without query parameters it returns
162	// the current revision; a single positive decimal revision parameter
163	// selects a historical revision.
164	func (s *store) getRef(w http.ResponseWriter, rawQuery, name string) {
165		revision, ok := parseRefRevisionQuery(rawQuery)
166		if !ok {
167			writeError(w, http.StatusBadRequest, "invalid_request")
168			return
169		}
170		rev, code := s.refAt(name, revision)
171		if code != "" {
172			writeError(w, http.StatusNotFound, code)
173			return
174		}
175		writeRef(w, http.StatusOK, name, rev)
176	}
177	
178	// refObjectEntry handles GET on /v1/refs/{name}/object.
179	func (s *store) refObjectEntry(w http.ResponseWriter, r *http.Request, rawName, rawQuery string) {
180		if r.Method != http.MethodGet {
181			w.Header().Set("Allow", http.MethodGet)
182			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
183			return
184		}
185		name, ok := decodeRefName(rawName)
186		if !ok {
187			writeError(w, http.StatusBadRequest, "invalid_ref")
188			return
189		}
190		revision, ok := parseRefRevisionQuery(rawQuery)
191		if !ok {
192			writeError(w, http.StatusBadRequest, "invalid_request")
193			return
194		}
195		rev, obj, code := s.resolveRefObject(name, revision)
196		if code != "" {
197			status := http.StatusFailedDependency
198			if code != "reference_target_missing" {
199				status = http.StatusNotFound
200			}
201			writeError(w, status, code)
202			return
203		}
204		w.Header().Set("Content-Type", "application/octet-stream")
205		w.Header().Set("Content-Length", strconv.Itoa(obj.size))
206		w.Header().Set("X-CidVault-CID", rev.cid)
207		w.Header().Set("X-CidVault-Ref-Revision", strconv.FormatInt(rev.revision, 10))
208		for _, chunk := range obj.chunks {
209			_, _ = w.Write(chunk)
210		}
211	}
