213	// parseRefRevisionQuery parses the optional single positive-decimal
214	// revision query parameter. No parameters means the current revision
215	// (zero); anything else (unknown keys, repeated values, non-integers,
216	// zero or negative) is invalid.
217	func parseRefRevisionQuery(rawQuery string) (int64, bool) {
218		query, err := url.ParseQuery(rawQuery)
219		if err != nil {
220			return 0, false
221		}
222		var revision int64
223		for key, values := range query {
224			if key != "revision" || len(values) != 1 {
225				return 0, false
226			}
227			v, ok := parseAuditInt(values[0])
228			if !ok || v < 1 {
229				return 0, false
230			}
231			revision = v
232		}
233		return revision, true
234	}
